(function () {
  const LX = globalThis.LX;
  const { T, H, P, STORY, TIP, WARN, FUN, BIG, JOB, CMD, TABLE, ANAT, PRE, THINK, STEPS, TRY } = LX.b;
  const { mcq, cmd } = LX.Q;
  const M = LX.M;
  const GI = () => LX.gitInternals;
  const gOf = (sh, dir) => {
    const n = sh.fs.lookup(dir + '/.git');
    return n && n.git;
  };
  const headOf = (g) => GI().headId(g);
  const countOf = (g) => {
    const h = headOf(g);
    return h ? GI().ancestors(g, h).size : 0;
  };
  const msgOf = (g) => {
    const h = headOf(g);
    return h && g.commits[h] ? g.commits[h].msg : '';
  };

  const GIT0 = ['sudo apt install -y git', 'git config --global init.defaultBranch main', 'git config --global user.name "Asha Rao"', 'git config --global user.email asha@example.com'];

  const CONF_LAB = GIT0.concat(['mkdir ~/srv', 'cd ~/srv', 'git init', 'printf "name=web\\nport=80\\n" > app.conf', 'git add .', 'git commit -m "base config"', 'git switch -c feature/port', 'sed -i "s/port=80/port=8080/" app.conf', 'git commit -am "port 8080"', 'git switch main', 'sed -i "s/port=80/port=9090/" app.conf', 'git commit -am "port 9090"', 'cd ~']);
  const CONF_FIX = ['cd ~/srv', 'git merge feature/port', 'printf "name=web\\nport=8080\\n" > app.conf', 'git add app.conf', 'git commit -m "merge feature/port"', 'git log --oneline --graph'];
  const TEAM_LAB = GIT0.concat(['git init --bare ~/origin.git', 'git clone ~/origin.git ~/seed', 'cd ~/seed', 'echo "# Team site" > README.md', 'git add .', 'git commit -m "initial commit"', 'git push -u origin main', 'cd ~']);
  const TEAM_FIX = ['git clone ~/origin.git ~/work', 'cd ~/work', 'git switch -c fix-typo', 'echo "# Team website" > README.md', 'git commit -am "Fix typo in the title"', 'git push -u origin fix-typo', 'git branch -vv'];
  const REV_LAB = GIT0.concat(['mkdir ~/shop', 'cd ~/shop', 'git init', 'echo "price=100" > price.txt', 'git add .', 'git commit -m "add price"', 'echo "price=0" > price.txt', 'git commit -am "oops: everything is free"', 'echo "tax=18" > tax.txt', 'git add .', 'git commit -m "add tax"', 'cd ~']);
  const REV_FIX = ['cd ~/shop', 'git log --oneline', 'git revert --no-edit HEAD~1', 'git log --oneline'];
  const LOST_LAB = GIT0.concat(['mkdir ~/lab', 'cd ~/lab', 'git init', 'echo v1 > app', 'git add .', 'git commit -m "v1"', 'echo v2 > app', 'git commit -am "v2: big feature"', 'echo v3 > app', 'git commit -am "v3: bugfix"', 'git reset --hard HEAD~2', 'cd ~']);
  const LOST_FIX = ['cd ~/lab', 'git reflog', 'git reset --hard HEAD@{1}', 'git log --oneline'];
  const IGN_LAB = GIT0.concat(['mkdir -p ~/app/__pycache__', 'cd ~/app', 'git init', 'echo "print(1)" > main.py', 'echo "DB_PASSWORD=secret" > .env', 'echo "log" > debug.log', 'echo "x" > __pycache__/main.cpython.pyc', 'cd ~']);
  const IGN_FIX = ['cd ~/app', 'printf ".env\\n*.log\\n__pycache__/\\n" > .gitignore', 'git status -s', 'git add .', 'git commit -m "Add app and gitignore"', 'git ls-files'];
  const REB_LAB = GIT0.concat(['mkdir ~/rb', 'cd ~/rb', 'git init', 'echo 1 > a', 'git add .', 'git commit -m "base"', 'git switch -c feature', 'echo f > f', 'git add .', 'git commit -m "feature work"', 'git switch main', 'echo m > m', 'git add .', 'git commit -m "main moved on"', 'cd ~']);
  const REB_FIX = ['cd ~/rb', 'git switch feature', 'git rebase main', 'git switch main', 'git merge feature', 'git log --oneline --graph'];
  const NOTES_FIX = GIT0.concat(['mkdir ~/notes', 'cd ~/notes', 'git init', 'echo "buy milk" > todo.txt', 'git add todo.txt', 'git commit -m "first todo"', 'echo "call mom" >> todo.txt', 'git commit -am "second todo"', 'git log --oneline']);

  const Q_REPO = GIT0.concat(['mkdir ~/p', 'cd ~/p', 'git init', 'echo one > f.txt', 'git add .', 'git commit -m "first"', 'echo two >> f.txt', 'git commit -am "second"', 'echo three >> f.txt', 'git commit -am "third"']);

  LX.topics.push({
    id: 'git',
    part: 5,
    no: 35,
    key: '⎇',
    mins: 80,
    title: T('Git: Version Control for Admins and DevOps', 'Git: Admins aur DevOps ke liye Version Control'),
    blurb: T('Every job in this field uses Git: scripts, configs, Ansible, Docker files, all live in repositories. Commits, branches, merges and conflicts, remotes and the pull/push team workflow, undoing mistakes with revert and reflog, rebase, .gitignore, hooks and tags.', 'Is field ki har job Git use karti hai: scripts, configs, Ansible, Docker files, sab repositories mein rehte hain. Commits, branches, merges aur conflicts, remotes aur pull/push team workflow, revert aur reflog se galtiyan sudharna, rebase, .gitignore, hooks aur tags.'),
    blocks: [
      BIG(
        'Git is a **time machine and a teamwork tool for files**. It remembers every version of every file, who changed it, when and why, lets you go back to any moment, and lets ten people edit the same project without overwriting each other. For an admin or DevOps engineer it is not optional: scripts, server configs, Ansible playbooks, Dockerfiles and Terraform code all live in Git, and **changes reach production through Git** (pull request, review, merge, deploy).',
        'Git **files ke liye time machine aur teamwork ka tool** hai. Ye har file ka har version yaad rakhta hai, kisne badla, kab aur kyun, tumhe kisi bhi pal par wapas jane deta hai, aur das log ek hi project ko bina ek doosre ka kaam mitaye edit kar sakte hain. Admin ya DevOps engineer ke liye ye optional nahi: scripts, server configs, Ansible playbooks, Dockerfiles aur Terraform code sab Git mein rehte hain, aur **production mein badlav Git ke raste pahunchte hain** (pull request, review, merge, deploy).'
      ),
      STORY(
        'Think of writing a book with friends. Instead of mailing "book_final_v2_REAL_final.docx" around, there is one shared notebook where every change is a numbered page-set with a note: "Asha: fixed chapter 3 typo". You can flip back to any page-set, try a wild idea on a separate copy (a branch) and only merge it into the book if it works.',
        'Socho dosto ke saath kitab likh rahe ho. "book_final_v2_REAL_final.docx" mail karne ke bajay ek shared notebook hai jisme har badlav ek numbered page-set hai aur ek note: "Asha: chapter 3 ki typo theek ki". Tum kisi bhi page-set par wapas ja sakte ho, ajeeb idea alag copy (branch) par try karo aur tabhi kitab mein milao jab chal jaye.'
      ),
      H('First: install and introduce yourself', 'Pehle: install karo aur apna parichay do'),
      P('Git is not preinstalled on a minimal server. Install it, then tell Git who you are: the name and e-mail are stamped on every commit you make.', 'Minimal server par Git pehle se nahi hota. Install karo, phir Git ko batao tum kaun ho: tumhare har commit par naam aur e-mail ki mohar lagti hai.'),
      CMD(GIT0.concat(['git --version', 'git config --global --list']), 'init.defaultBranch main makes new repositories start on "main" (the modern name instead of "master"). --global writes to ~/.gitconfig and applies to every repository of this user; without it, the setting is per repository.', 'init.defaultBranch main naye repositories ko "main" se shuru karta hai (modern naam, "master" ki jagah). --global ~/.gitconfig mein likhta hai aur is user ki har repository par lagu hota hai; uske bina setting sirf us repository ki hoti hai.'),
      H('The three areas (the idea that makes Git click)', 'Teen jagahein (wo idea jisse Git samajh aata hai)'),
      PRE(`  working tree           staging area (index)          repository (.git)
  the files you edit     what goes in the NEXT commit  the saved history
        |                         |                           |
        |------- git add -------->|                           |
        |                         |------- git commit ------->|
        |<------------------------ git restore / checkout ----|`),
      P('You edit files in the **working tree**. `git add` copies the changes you choose into the **staging area** (a drafting table). `git commit` takes everything staged and stores it forever as a **commit** in the repository. This lets you build clean commits: edit ten files, commit only the three that belong together.', 'Tum **working tree** mein files edit karte ho. `git add` jo badlav tum chuno unhe **staging area** (drafting table) mein copy karta hai. `git commit` jo kuch staged hai use hamesha ke liye repository mein **commit** ki tarah rakh deta hai. Isse saaf commits banate hain: das files edit karo, sirf wo teen commit karo jo saath ki hain.'),
      TABLE(
        [
          ['commit', 'a snapshot of the whole project plus author, time, message and a pointer to its parent(s); identified by a 40-character hash (usually shown as 7)', 'poore project ka snapshot, saath mein author, samay, message aur parent ka pointer; 40-akshar ke hash se pehchana jata hai (aam taur par 7 dikhte hain)'],
          ['branch', 'a movable label on a commit: a lightweight parallel line of work', 'ek commit par lagi hilne wali label: kaam ki halki parallel line'],
          ['HEAD', 'where you are now: normally "the branch you are on"', 'tum abhi kahan ho: aam taur par "jis branch par ho"'],
          ['merge', 'join two lines of work together', 'kaam ki do lines ko jodna'],
          ['remote', 'another copy of the repository, usually on a server (GitHub, GitLab, your own box); the default name is origin', 'repository ki doosri copy, aam taur par server par (GitHub, GitLab, apna server); default naam origin'],
          ['clone / fetch / pull / push', 'copy a repo / download news / download and merge news / upload your commits', 'repo ki copy / khabar download / download aur merge / apne commits upload'],
        ],
        'Word',
        'Shabd'
      ),
      H('Your first repository', 'Tumhari pehli repository'),
      CMD(['mkdir ~/notes', 'cd ~/notes', 'git init', 'echo "buy milk" > todo.txt', 'git status', 'git add todo.txt', 'git status', 'git commit -m "first todo"', 'git log'], 'git status is the command you will type 100 times a day: it tells which files are untracked (new), modified, and staged. After add the file is "Changes to be committed"; after commit the tree is clean.', 'git status wo command hai jo tum din mein 100 baar type karoge: batata hai kaun si files untracked (nayi), modified aur staged hain. add ke baad file "Changes to be committed" hoti hai; commit ke baad tree clean.'),
      P('A good commit message says **why**, in the imperative, in a short first line: "Fix backup script when /var is full", not "changes" or "asdf". Months later, `git log` is the diary of the project and your future self (and the on-call engineer at 3 a.m.) will read it.', 'Achha commit message **kyun** batata hai, imperative mein, chhoti pehli line: "Fix backup script when /var is full", "changes" ya "asdf" nahi. Mahino baad `git log` project ki diary hai aur tumhara future-self (aur raat 3 baje on-call engineer) use padhega.'),
      CMD(['echo "call mom" >> todo.txt', 'git status -s', 'git diff', 'git commit -am "Add second todo"', 'git log --oneline', 'git show --stat', 'git diff HEAD~1 HEAD'], 'git diff shows the unstaged changes (add --staged for staged ones). commit -a stages every already-tracked modified file for you (it does not take new files). --oneline is the compact history; show displays one commit; diff A B compares two points in time. status -s is the short format: " M" modified, "A " added, "??" untracked.', 'git diff unstaged badlav dikhata hai (staged ke liye --staged lagao). commit -a har pehle se tracked modified file ko khud stage kar deta hai (nayi files nahi leta). --oneline compact history hai; show ek commit dikhata hai; diff A B do samay ki tulna karta hai. status -s chhota format hai: " M" modified, "A " added, "??" untracked.'),
      ANAT([
        ['git', 'cmd', 'the program', 'program'],
        ['log', 'arg', 'subcommand: show history', 'subcommand: history dikhao'],
        ['--oneline', 'opt', 'one line per commit', 'har commit ek line'],
        ['--graph', 'opt', 'draw the branch lines with ASCII art', 'branch lines ASCII art se banao'],
        ['--all', 'opt', 'all branches, not just the current one', 'sirf current nahi, saari branches'],
        ['-- file', 'arg', 'only commits that touched this path', 'sirf wo commits jinhone is path ko chhua'],
      ]),
      TIP('Make `git log` answer your questions: `--author=Asha`, `--since="2 weeks ago"`, `--grep=backup` (message search), `-3` (last three), `--stat` (files changed), `-p` (the actual patch), and `git log -- path/to/file` for one file. `git blame file` shows who last changed each line and in which commit: the first tool to reach for when something broke.', '`git log` se apne sawalon ke jawab lo: `--author=Asha`, `--since="2 weeks ago"`, `--grep=backup` (message search), `-3` (aakhri teen), `--stat` (kaun si files badlin), `-p` (asli patch), aur ek file ke liye `git log -- path/to/file`. `git blame file` dikhata hai har line ko aakhri baar kisne aur kis commit mein badla: kuch toote to sabse pehle yahi tool.'),
      CMD(['git log --oneline --graph --all', 'git log --author="Asha" --oneline -2', 'git log --grep=second --format="%h %an %s"', 'git log --stat -1', 'git blame todo.txt', 'git shortlog -sn'], 'The format placeholders: %h short hash, %an author name, %s subject. shortlog -sn counts commits per person.', 'Format placeholders: %h chhota hash, %an author ka naam, %s subject. shortlog -sn har vyakti ke commits ginta hai.'),
      H('.gitignore: files Git must never touch', '.gitignore: wo files jinhe Git ko kabhi nahi chhuna'),
      P('Some files must never enter the history: **secrets** (.env, keys, passwords), logs, compiled output, caches, editor junk. List patterns in a `.gitignore` file at the top of the repository. A secret that was committed once is in the history forever (even after you delete the file), so ignore first, commit later; a leaked key must be **rotated**, not just removed.', 'Kuch files history mein kabhi nahi aani chahiye: **secrets** (.env, keys, passwords), logs, compiled output, caches, editor kachra. Patterns repository ke top par `.gitignore` file mein likho. Jo secret ek baar commit ho gaya wo history mein hamesha rehta hai (file delete karne par bhi), isliye pehle ignore, phir commit; leak hui key **rotate** karni padti hai, sirf hatana kaafi nahi.'),
      CMD(['mkdir -p ~/app/__pycache__', 'cd ~/app', 'git init -q', 'echo "print(1)" > main.py', 'echo "DB_PASSWORD=secret" > .env', 'echo log > debug.log', 'echo x > __pycache__/main.pyc', 'git status -s', 'printf ".env\\n*.log\\n__pycache__/\\n" > .gitignore', 'git status -s', 'git add -A', 'git commit -qm "Add app"', 'git ls-files'], 'Before the .gitignore, status lists .env, debug.log and the cache as untracked: one careless git add . would publish the password. After it, only main.py and .gitignore remain. Commit the .gitignore itself so the whole team shares it.', '.gitignore se pehle status .env, debug.log aur cache ko untracked dikhata hai: ek laparwah git add . password publish kar deta. Uske baad sirf main.py aur .gitignore bachte hain. .gitignore ko khud commit karo taaki poori team use kare.'),
      H('Branches and merging', 'Branches aur merging'),
      P('A branch is just a label on a commit, so creating one is instant and free. The habit: **never work directly on main**. For every task create a branch, commit there, then merge it back. If the experiment fails, delete the branch and main never knew.', 'Branch bas ek commit par label hai, isliye banana turant aur muft hai. Aadat: **main par seedha kaam kabhi nahi**. Har task ke liye branch banao, wahin commit karo, phir wapas merge karo. Experiment fail ho to branch delete karo, main ko pata bhi nahi chala.'),
      CMD(['cd ~/notes', 'git switch -c feature/shopping', 'echo "eggs" >> todo.txt', 'git commit -am "Add eggs"', 'git branch', 'git switch main', 'cat todo.txt', 'git merge feature/shopping', 'cat todo.txt', 'git log --oneline --graph --all', 'git branch -d feature/shopping'], 'switch -c creates and enters a branch (the older spelling is git checkout -b). On main the new line does not exist until the merge. Here main had not moved, so Git simply slid the label forward: a "fast-forward". -d deletes a branch that is already merged (safe); -D forces.', 'switch -c branch banata aur usme jata hai (purani spelling git checkout -b). main par nayi line merge se pehle nahi hoti. Yahan main aage nahi badha tha, isliye Git ne bas label aage khisaka di: "fast-forward". -d wo branch delete karta hai jo merge ho chuki (surakshit); -D zabardasti.'),
      H('Merge conflicts: not a disaster, just a question', 'Merge conflicts: museebat nahi, bas ek sawal'),
      P('When two branches changed **the same lines**, Git cannot decide for you. It stops, marks the file and asks. The markers: everything between `<<<<<<< HEAD` and `=======` is YOUR side, between `=======` and `>>>>>>> branch` is THEIR side. You edit the file to the final text you want, remove the markers, `git add` it and `git commit`.', 'Jab do branches ne **wahi lines** badli hon, Git tumhare liye faisla nahi kar sakta. Ruk jata hai, file par nishan lagata hai aur poochta hai. Nishan: `<<<<<<< HEAD` aur `=======` ke beech TUMHARA side, `=======` aur `>>>>>>> branch` ke beech UNKA side. File ko apne chahe final text mein edit karo, nishan hatao, `git add` aur `git commit`.'),
      STEPS([
        ['`git merge other` says CONFLICT. Do not panic: `git status` lists the "Unmerged paths" (the files to fix).', '`git merge other` CONFLICT kehta hai. Ghabrao mat: `git status` "Unmerged paths" (theek karne wali files) batata hai.'],
        ['Open each file, look for the `<<<<<<<` markers, decide the right final text, delete all three marker lines.', 'Har file kholo, `<<<<<<<` nishan dhundo, sahi final text tay karo, teeno nishan wali lines hatao.'],
        ['`git add file` tells Git "this one is resolved". `git diff` before it helps you check.', '`git add file` Git ko batata hai "ye resolve ho gayi". Pehle `git diff` se check karna madad karta hai.'],
        ['`git commit` finishes the merge (the message is pre-filled). Changed your mind? `git merge --abort` returns to before the merge.', '`git commit` merge poora karta hai (message pehle se bhara hota hai). Mann badla? `git merge --abort` merge se pehle wali halat mein le jata hai.'],
      ]),
      CMD(CONF_LAB.slice(GIT0.length).concat(['cd ~/srv', 'git merge feature/port', 'git status -s', 'cat app.conf']), 'Both branches changed the port line from 80, to different values: a true conflict. cat shows the markers. Resolving is just editing: pick 8080, 9090 or something else.', 'Dono branches ne port line 80 se alag-alag values mein badli: sachha conflict. cat nishan dikhata hai. Resolve karna bas edit hai: 8080, 9090 ya kuch aur chuno.'),
      CMD(['printf "name=web\\nport=8080\\n" > app.conf', 'git add app.conf', 'git commit -m "Merge feature/port, keep 8080"', 'git log --oneline --graph'], 'The graph now shows a merge commit with two parents: the two lines of work joined. This is what the history of a real team looks like.', 'Graph ab do parents wala merge commit dikhata hai: kaam ki do lines jud gayin. Asli team ki history aisi hi dikhti hai.'),
      TIP('Prevent most conflicts with small branches that live a day or two, `git pull` often, and by talking to the person who edits the same file. Conflicts in generated files (lock files) are usually fixed by regenerating the file, not by hand-editing.', 'Zyadatar conflicts rokne ke liye: chhoti branches jo ek-do din jeeti hon, baar baar `git pull`, aur jo vyakti wahi file edit karta hai usse baat. Generated files (lock files) ke conflicts aam taur par haath se edit karne ke bajay file dobara banane se theek hote hain.'),
      H('Remotes: working with a team', 'Remotes: team ke saath kaam'),
      P('A remote is another copy of the repository. In real life it is on GitHub or GitLab; the simplest remote is a **bare repository** on a server (a repository with only history, no working files). Here we build the same setup on one machine: a bare `origin.git` plus two working copies, like two colleagues.', 'Remote repository ki doosri copy hai. Asli zindagi mein ye GitHub ya GitLab par hoti hai; sabse saral remote server par **bare repository** hai (sirf history, working files nahi). Yahan wahi setup ek machine par banate hain: ek bare `origin.git` aur do working copies, jaise do colleagues.'),
      CMD(['git init --bare ~/origin.git', 'git clone ~/origin.git ~/asha', 'cd ~/asha', 'echo "# Team site" > README.md', 'git add README.md', 'git commit -m "initial commit"', 'git push -u origin main', 'git remote -v', 'git branch -vv'], 'clone copies a repository and sets remote "origin" for you. push uploads your commits; -u remembers that local main tracks origin/main, so later a plain git push or git pull knows where to go. branch -vv shows the tracking and whether you are ahead or behind.', 'clone repository ki copy karta hai aur remote "origin" khud set karta hai. push tumhare commits upload karta hai; -u yaad rakhta hai ki local main origin/main ko track karta hai, isliye baad mein seedha git push ya git pull jaanta hai kahan jana hai. branch -vv tracking aur ahead/behind dikhata hai.'),
      CMD(['cd ~', 'git clone ~/origin.git ~/ravi', 'cd ~/ravi', 'git config user.name "Ravi Kumar"', 'git config user.email ravi@example.com', 'echo "Contact: ravi@example.com" >> README.md', 'git commit -am "Add contact line"', 'git push', 'cd ~/asha', 'git fetch', 'git status -sb', 'git pull', 'cat README.md', 'git log --oneline --graph'], 'Ravi (a second clone with his own identity) pushes. Asha runs git fetch: it downloads the news but changes nothing yet, and status -sb shows [behind 1]. git pull = fetch + merge, bringing the work in. That is the daily rhythm: pull, work, commit, push.', 'Ravi (apni pehchan wala doosra clone) push karta hai. Asha git fetch chalati hai: khabar download hoti hai par abhi kuch badalta nahi, aur status -sb [behind 1] dikhata hai. git pull = fetch + merge, kaam andar le aata hai. Roz ki lay yahi: pull, kaam, commit, push.'),
      WARN('If someone pushed before you, your `git push` is **rejected** ("non-fast-forward", "fetch first"). The answer is never `--force`: it overwrites their work on the server. Run `git pull` (resolve any conflict), then push again. `--force-with-lease` is the polite version for your OWN branch after a rebase; on `main`, forcing is a firing offence in many teams.', 'Agar tumse pehle kisi ne push kiya, tumhara `git push` **reject** hota hai ("non-fast-forward", "fetch first"). Jawab kabhi `--force` nahi: ye server par unka kaam mita deta hai. `git pull` chalao (conflict ho to resolve), phir push. `--force-with-lease` tumhari APNI branch ke liye rebase ke baad ka vinamra roop hai; `main` par force karna kai teams mein naukri jane ki wajah hai.'),
      TABLE(
        [
          ['git clone URL [dir]', 'copy a remote repo and set origin', 'remote repo ki copy karo aur origin set karo'],
          ['git remote -v  /  git remote add NAME URL', 'list / add remotes', 'remotes dekho / jodo'],
          ['git fetch', 'download new commits, change nothing locally', 'naye commits download, local kuch nahi badalta'],
          ['git pull  (= fetch + merge)', 'update the current branch; --rebase to replay instead of merge', 'current branch update karo; merge ke bajay replay ke liye --rebase'],
          ['git push -u origin BRANCH', 'upload a branch and set tracking', 'branch upload karo aur tracking set karo'],
          ['git push origin --delete BRANCH', 'delete a remote branch', 'remote branch delete karo'],
          ['git remote show origin', 'details of a remote and tracking', 'remote aur tracking ka vivaran'],
        ],
        'Command',
        'Command'
      ),
      P('**Pull requests / merge requests** (GitHub, GitLab) are a web layer on top of this: you push a branch, open a request, colleagues review the diff, CI runs the tests, and the merge button does `git merge` for you. The commands are exactly the ones above; learn them well and any platform feels familiar.', '**Pull requests / merge requests** (GitHub, GitLab) isi ke upar web layer hain: tum branch push karte ho, request kholte ho, colleagues diff review karte hain, CI tests chalata hai, aur merge button tumhare liye `git merge` karta hai. Commands wahi hain jo upar hain; unhe achhe se seekho to koi bhi platform jaana-pehchana lagta hai.'),
      H('Authenticating to a real server', 'Asli server se authentication'),
      TABLE(
        [
          ['git@github.com:org/repo.git', 'SSH URL: authenticates with your SSH key (the same keys as in the SSH lesson); recommended for admins and servers', 'SSH URL: tumhari SSH key se authenticate hota hai (SSH lesson wali wahi keys); admins aur servers ke liye behtar'],
          ['https://github.com/org/repo.git', 'HTTPS URL: asks for a username and a personal access token (never your account password)', 'HTTPS URL: username aur personal access token maangta hai (account password kabhi nahi)'],
          ['deploy key', 'a read-only SSH key attached to ONE repository: what a production server should use to pull code', 'ek repository se juda read-only SSH key: production server ko code pull karne ke liye yahi use karni chahiye'],
        ],
        'Form',
        'Roop'
      ),
      TIP('A server that only needs to **deploy** code should hold a read-only deploy key, not an engineer\'s personal key. And no password or token ever belongs inside a repository: use environment variables, a secrets manager or Ansible Vault.', 'Jis server ko sirf code **deploy** karna hai uske paas read-only deploy key honi chahiye, kisi engineer ki personal key nahi. Aur repository ke andar koi password ya token kabhi nahi: environment variables, secrets manager ya Ansible Vault use karo.'),
      H('Undoing things (and not panicking)', 'Cheezein undo karna (bina ghabraye)'),
      P('Git almost never loses committed work. Choose the right undo by asking **where is the mistake?**', 'Git commit kiya hua kaam lagbhag kabhi nahi khota. Sahi undo chuno ye poochkar: **galti kahan hai?**', ),
      TABLE(
        [
          ['edited a file, want the old version back', 'git restore FILE  (throws the edit away)', 'git restore FILE  (edit fenk deta hai)'],
          ['staged a file by mistake', 'git restore --staged FILE  (keeps your edit)', 'git restore --staged FILE  (tumhara edit rehta hai)'],
          ['typo in the last commit message, or forgot a file', 'git commit --amend  (rewrites the last commit: only if not pushed)', 'git commit --amend  (aakhri commit dobara likhta hai: sirf jab push na hui ho)'],
          ['a bad commit that others already have', 'git revert COMMIT  (adds a NEW commit that cancels it: history stays honest)', 'git revert COMMIT  (use cancel karne wala NAYA commit jodta hai: history imaandar rehti hai)'],
          ['undo local commits, keep the work', 'git reset --soft HEAD~1  (changes stay staged)  /  --mixed (default, unstaged)', 'local commits undo karo, kaam rakho: git reset --soft HEAD~1  (changes staged rehte hain)  /  --mixed (default, unstaged)'],
          ['undo local commits AND the work', 'git reset --hard HEAD~1  (destructive for uncommitted work)', 'git reset --hard HEAD~1  (uncommitted kaam ke liye vinashkari)'],
          ['"I lost a commit!"', 'git reflog  then  git reset --hard HEAD@{N}', 'git reflog  phir  git reset --hard HEAD@{N}'],
        ],
        'Situation',
        'Sthiti'
      ),
      CMD(REV_LAB.slice(GIT0.length).concat(['cd ~/shop', 'git log --oneline', 'git revert --no-edit HEAD~1', 'cat price.txt', 'git log --oneline']), 'The middle commit set every price to zero, but a later commit (the tax) already built on top of it. revert HEAD~1 creates a new commit that undoes only that change; history is not rewritten, so it is safe even after pushing.', 'Beech wale commit ne har price zero kar di, par baad ke commit (tax) ne uske upar kaam kar liya. revert HEAD~1 naya commit banata hai jo sirf wahi badlav undo karta hai; history dobara nahi likhi jati, isliye push ke baad bhi surakshit.'),
      CMD(LOST_LAB.slice(GIT0.length).concat(['cd ~/lab', 'git log --oneline', 'git reflog', 'git reset --hard HEAD@{1}', 'git log --oneline', 'cat app']), 'After the hard reset the log shows only v1: the two other commits look gone. But the reflog is a diary of every place HEAD has been; HEAD@{1} is "where I was one move ago". Resetting to it brings v3 back. Reflog entries live for about 90 days, so you have time.', 'Hard reset ke baad log sirf v1 dikhata hai: baaki do commits gaye lagte hain. Par reflog har us jagah ki diary hai jahan HEAD raha; HEAD@{1} matlab "ek move pehle main kahan tha". Wahan reset karne se v3 wapas aa jata hai. Reflog entries lagbhag 90 din rehti hain, to samay hai.'),
      WARN('`git reset --hard`, `git clean -fd` and `git checkout -- .` destroy **uncommitted** work and the reflog cannot save it (it was never committed). Run `git status` and `git diff` first. And the rule for rewriting history (amend, reset, rebase): **only rewrite commits that nobody else has**. Once pushed and shared, use revert.', '`git reset --hard`, `git clean -fd` aur `git checkout -- .` **uncommitted** kaam nasht karte hain aur reflog use bacha nahi sakta (wo kabhi commit hi nahi hua). Pehle `git status` aur `git diff` chalao. Aur history badalne (amend, reset, rebase) ka niyam: **sirf wo commits badlo jo kisi aur ke paas nahi**. Push aur share hone ke baad revert use karo.'),
      H('Stash: put your work on a shelf', 'Stash: apna kaam shelf par rakho'),
      CMD(['cd ~/notes', 'echo "half-written idea" >> todo.txt', 'git stash push -m "wip idea"', 'git status -s', 'git stash list', 'git switch main', 'git stash pop', 'cat todo.txt'], 'You are in the middle of something and an urgent fix arrives: stash puts your uncommitted changes on a shelf and gives you a clean tree; pop brings them back (apply keeps the stash entry too). Other stash commands: show, drop, clear.', 'Tum kisi kaam ke beech ho aur zaroori fix aa gaya: stash tumhare uncommitted badlav shelf par rakh deta hai aur saaf tree deta hai; pop unhe wapas laata hai (apply stash entry bhi rakhta hai). Baaki stash commands: show, drop, clear.'),
      H('Rebase: a straight history (and when NOT to use it)', 'Rebase: seedhi history (aur kab use NAHI karna)'),
      P('Merge keeps history as it happened (a diamond shape). **Rebase** takes your branch commits and **replays them on top of** the latest main, so the history is a straight line. It rewrites those commits (new hashes), so it belongs to **your own, unpushed branches**. Golden rule: *never rebase commits that others have already pulled.*', 'Merge history ko waise rakhta hai jaisi hui (heera shape). **Rebase** tumhari branch ke commits ko latest main ke **upar dobara chala deta hai**, isliye history seedhi line hoti hai. Ye un commits ko dobara likhta hai (naye hash), isliye **tumhari apni, unpushed branches** ke liye hai. Sunehra niyam: *jin commits ko doosre pull kar chuke hain unhe kabhi rebase mat karo.*'),
      CMD(REB_LAB.slice(GIT0.length).concat(['cd ~/rb', 'git log --oneline --graph --all', 'git switch feature', 'git rebase main', 'git switch main', 'git merge feature', 'git log --oneline --graph']), 'Before: two diverged lines (feature work and "main moved on"). The rebase replays "feature work" after "main moved on"; the final merge is a plain fast-forward, so there is no merge commit and the graph is one straight line. If a replayed commit conflicts you fix it and run git rebase --continue (or --abort to cancel, --skip to drop that commit).', 'Pehle: do alag hui lines (feature work aur "main moved on"). Rebase "feature work" ko "main moved on" ke baad dobara chalata hai; aakhri merge seedha fast-forward hai, isliye merge commit nahi aur graph ek seedhi line. Agar replay hua commit conflict kare to theek karo aur git rebase --continue chalao (--abort cancel, --skip us commit ko chhodta hai).'),
      CMD(['mkdir ~/sq', 'cd ~/sq', 'git init -q', 'echo 1 > f', 'git add .', 'git commit -qm "start"', 'echo 2 >> f', 'git commit -qam "wip"', 'echo 3 >> f', 'git commit -qam "wip 2"', 'echo 4 >> f', 'git commit -qam "fix typo"', 'git log --oneline', 'GIT_SEQUENCE_EDITOR="sed -i \'3,4s/^pick/squash/\'" git rebase -i HEAD~3', 'git log --oneline'], 'Interactive rebase (-i) lets you reshape your own unpushed commits: pick, reword, squash (meld into the previous one), fixup, drop. Normally an editor opens with the list; here we scripted the edit with GIT_SEQUENCE_EDITOR so three messy commits become one clean commit before a pull request.', 'Interactive rebase (-i) tumhe apne unpushed commits ka shape badalne deta hai: pick, reword, squash (pichhle mein milao), fixup, drop. Aam taur par editor list ke saath khulta hai; yahan humne GIT_SEQUENCE_EDITOR se edit script kar diya, to teen gande commits pull request se pehle ek saaf commit ban gaye.'),
      CMD(['cd ~/rb', 'git switch -c hotfix', 'echo fix > hot.txt', 'git add .', 'git commit -m "Hotfix"', 'git switch main', 'git cherry-pick hotfix', 'git log --oneline -3'], 'cherry-pick copies one commit onto the current branch (a new commit with the same change). Handy for pulling a single hotfix into a release branch without merging everything else.', 'cherry-pick ek commit ko current branch par copy karta hai (wahi badlav, naya commit). Baaki sab merge kiye bina ek hotfix ko release branch mein lene ke liye kaam ka.'),
      H('Tags and releases', 'Tags aur releases'),
      CMD(['cd ~/notes', 'git tag v1.0', 'git tag -a v1.1 -m "Shopping list release"', 'git tag', 'git describe', 'git show v1.1 --stat', 'git archive -o /tmp/notes-v1.1.tar.gz v1.1', 'tar tzf /tmp/notes-v1.1.tar.gz', 'git push --tags'], 'A tag is a permanent name for a commit: a release. Annotated tags (-a) also store who tagged it and a message. archive exports a clean copy of a version without the .git folder, ready to deploy or ship. Tags are not pushed by default: git push --tags (or git push origin v1.1).', 'Tag ek commit ka sthayi naam hai: ek release. Annotated tags (-a) ye bhi rakhte hain ki kisne tag kiya aur message. archive ek version ki saaf copy bina .git folder ke export karta hai, deploy ya bhejne ke liye taiyar. Tags default push nahi hote: git push --tags (ya git push origin v1.1).'),
      H('Hooks: automatic checks', 'Hooks: apne-aap hone wali checks'),
      P('A **hook** is a script in `.git/hooks/` that Git runs at a moment: `pre-commit` (before a commit is created), `commit-msg`, `pre-push`, and on servers `post-receive` (deploy after a push). If a pre-commit hook exits non-zero the commit is refused. Teams use it to run linters, `shellcheck` and secret scanners before bad code gets in.', '**Hook** `.git/hooks/` mein ek script hai jo Git ek khaas pal par chalata hai: `pre-commit` (commit banne se pehle), `commit-msg`, `pre-push`, aur servers par `post-receive` (push ke baad deploy). Agar pre-commit hook non-zero se nikle to commit mana ho jata hai. Teams linters, `shellcheck` aur secret scanners chalane ke liye use karti hain taaki kharab code andar na aaye.'),
      CMD(['mkdir ~/hk', 'cd ~/hk', 'git init -q', 'printf "#!/bin/sh\\nif grep -rq TODO . --include=*.sh; then echo \\"commit refused: remove TODO\\"; exit 1; fi\\n" > .git/hooks/pre-commit', 'chmod +x .git/hooks/pre-commit', 'echo "# TODO: fix" > run.sh', 'git add run.sh', 'git commit -m "add script"', 'echo "echo hi" > run.sh', 'git add run.sh', 'git commit -m "add script"'], 'The first commit is refused by the hook (exit 1); after the TODO is removed the same commit passes. --no-verify skips hooks: use it knowingly. Hooks live in .git (not shared by clone), so teams share them with a tool such as pre-commit or a folder with core.hooksPath.', 'Pehla commit hook ne mana kar diya (exit 1); TODO hatane ke baad wahi commit pass ho gaya. --no-verify hooks chhod deta hai: soch samajh kar use karo. Hooks .git mein rehte hain (clone se share nahi hote), isliye teams unhe pre-commit jaise tool ya core.hooksPath wale folder se share karti hain.'),
      H('Git for ops: how admins really use it', 'Ops ke liye Git: admins asal mein kaise use karte hain'),
      TABLE(
        [
          ['/etc under version control', 'keep configs in a repo (etckeeper does it automatically, committing on every apt run): every change has a who, when, why and a diff, and rollback is one command', 'configs ek repo mein rakho (etckeeper ye khud karta hai, har apt run par commit): har badlav ka kaun, kab, kyun aur diff hota hai, aur rollback ek command'],
          ['infrastructure as code', 'Ansible, Terraform, Docker and Kubernetes files in Git; the repository is the source of truth, servers follow it', 'Ansible, Terraform, Docker aur Kubernetes files Git mein; repository sach ka srot hai, servers uske peeche chalte hain'],
          ['GitOps / CI/CD', 'a merge to main triggers tests and a deploy: nobody types commands on production by hand', 'main mein merge se tests aur deploy chalte hain: production par koi haath se commands type nahi karta'],
          ['incident forensics', 'git log -p -- /path and git blame answer "what changed before it broke?"', 'git log -p -- /path aur git blame jawab dete hain "tootne se pehle kya badla?"'],
          ['branching styles', 'trunk-based (short branches into main) or Git Flow (develop/release/hotfix); know both names', 'trunk-based (main mein chhoti branches) ya Git Flow (develop/release/hotfix); dono ke naam jaano'],
        ],
        'Use',
        'Upyog'
      ),
      JOB('Interview staples: "Explain the difference between merge and rebase" (merge keeps history and makes a merge commit, rebase replays commits for a linear history and must not be used on shared commits), "How do you undo a commit that was pushed?" (git revert, never a force-push on a shared branch), "You deleted a branch by mistake" (git reflog, then git switch -c name SHA), "fetch vs pull" (pull = fetch + merge), and "what is a detached HEAD" (HEAD pointing at a commit instead of a branch: commit work there and it is easy to lose; create a branch with git switch -c). Also be ready to describe a pull-request workflow and how you keep secrets out of a repo.', 'Interview ke sadabahar sawal: "merge aur rebase mein antar batao" (merge history rakhta hai aur merge commit banata hai, rebase linear history ke liye commits replay karta hai aur shared commits par use nahi karna), "pushed commit kaise undo karoge?" (git revert, shared branch par force-push kabhi nahi), "branch galti se delete ho gayi" (git reflog, phir git switch -c naam SHA), "fetch vs pull" (pull = fetch + merge), aur "detached HEAD kya hai" (HEAD branch ki jagah commit ko point kare: wahan kiya kaam kho jana aasan hai; git switch -c se branch banao). Pull-request workflow aur repo se secrets door rakhne ka tareeka bhi batane ko taiyar raho.'),
      THINK('You ran git pull and got "CONFLICT" in a file you never touched. How is that possible, and what do you do?', 'Tumne git pull chalaya aur ek aisi file mein "CONFLICT" aaya jise tumne chhua bhi nahi. Ye kaise possible hai aur kya karoge?', 'You did touch it in an earlier local commit, or an old uncommitted change was carried along. A pull merges their new commits into your branch, and any file changed on both sides can conflict, even if you edited it days ago. Open it, resolve the markers, git add, git commit (or git merge --abort and look at git log origin/main first).', 'Tumne use pehle ke kisi local commit mein chhua tha, ya purana uncommitted badlav saath aa gaya. Pull unke naye commits tumhari branch mein merge karta hai, aur dono taraf badli har file conflict kar sakti hai, chahe tumne use din pehle edit kiya ho. File kholo, nishan resolve karo, git add, git commit (ya git merge --abort karke pehle git log origin/main dekho).'),
      H('Cheat sheet', 'Cheat sheet'),
      TABLE([
        ['git init ; git clone URL', 'start a repo / copy one', 'repo shuru karo / copy karo'],
        ['git status -s ; git diff ; git diff --staged', 'what changed', 'kya badla'],
        ['git add FILE ; git add -A ; git commit -m "why"', 'stage and save a snapshot', 'stage karo aur snapshot save karo'],
        ['git log --oneline --graph --all', 'history as a picture', 'history ek tasveer ki tarah'],
        ['git switch -c NAME ; git switch NAME ; git branch -d NAME', 'branches', 'branches'],
        ['git merge NAME ; git merge --abort', 'join / cancel a merge', 'jodo / merge cancel karo'],
        ['git fetch ; git pull ; git push -u origin NAME', 'sync with the remote', 'remote ke saath sync'],
        ['git restore FILE ; git restore --staged FILE', 'undo edits / unstage', 'edits undo / unstage'],
        ['git revert COMMIT', 'safe undo of a shared commit', 'shared commit ka surakshit undo'],
        ['git reflog ; git reset --hard HEAD@{N}', 'recover "lost" commits', '"khoye" commits wapas'],
        ['git stash push -m "msg" ; git stash pop', 'shelve work in progress', 'adhoora kaam shelf par'],
        ['git rebase main ; git cherry-pick SHA', 'linear history / copy one commit', 'seedhi history / ek commit copy'],
        ['git tag -a v1.0 -m "msg" ; git archive -o x.tgz v1.0', 'releases', 'releases'],
        ['.gitignore ; hooks/pre-commit', 'keep junk and secrets out; automatic checks', 'kachra aur secrets door; apne-aap checks'],
      ]),
    ],
    missions: [
      M('git-m1', 'Your first repository with two commits', 'Tumhari pehli repository, do commits ke saath', 'Install git and set your name and e-mail. Then create a repository in ~/notes, add a file todo.txt and make TWO commits (the second one after changing the file).', 'Git install karo aur apna naam aur e-mail set karo. Phir ~/notes mein repository banao, todo.txt file jodo aur DO commits banao (doosra file badalne ke baad).', 'apt install git ; git config ; mkdir+cd ; git init ; add ; commit ; edit ; commit -am', 'apt install git ; git config ; mkdir+cd ; git init ; add ; commit ; edit ; commit -am', (sh) => { const g = gOf(sh, '/home/learner/notes'); if (!g) return false; const h = headOf(g); return !!h && countOf(g) >= 2 && 'todo.txt' in g.commits[h].tree; }, NOTES_FIX, { testSolve: NOTES_FIX }),
      M('git-m2', 'Resolve a merge conflict', 'Merge conflict resolve karo', 'In ~/srv two branches changed the port line of app.conf differently. Merge feature/port into main, resolve the conflict by choosing port=8080 and finish the merge with a commit. (Use the lab button.)', '~/srv mein do branches ne app.conf ki port line alag badli. feature/port ko main mein merge karo, port=8080 chun kar conflict resolve karo aur commit se merge poora karo. (Lab button use karo.)', 'git merge feature/port ; edit file (no markers) ; git add ; git commit', 'git merge feature/port ; file edit (nishan nahi) ; git add ; git commit', (sh) => { const g = gOf(sh, '/home/learner/srv'); if (!g || g.merge) return false; const h = headOf(g); const cf = LX.cat(sh, '/home/learner/srv/app.conf'); return !!h && g.commits[h].parents.length === 2 && /port=8080/.test(cf) && !/[<>=]{7}/.test(cf); }, CONF_LAB.concat(CONF_FIX), { lab: { setup: CONF_LAB, en: 'a repo whose main and feature/port branches both changed the same line.', hi: 'repo jiski main aur feature/port branches ne ek hi line badli.' }, testSolve: CONF_LAB.concat(CONF_FIX) }),
      M('git-m3', 'Team workflow: clone, branch, push', 'Team workflow: clone, branch, push', 'A shared bare repository ~/origin.git already has the first commit. Clone it to ~/work, create a branch fix-typo, change the title in README.md to "# Team website", commit, and push the branch to origin (leave main untouched). (Use the lab button.)', 'Shared bare repository ~/origin.git mein pehla commit hai. Use ~/work mein clone karo, fix-typo branch banao, README.md ka title "# Team website" karo, commit karo, aur branch origin par push karo (main ko mat chhedo). (Lab button use karo.)', 'git clone ~/origin.git ~/work ; git switch -c fix-typo ; edit ; commit -am ; git push -u origin fix-typo', 'git clone ~/origin.git ~/work ; git switch -c fix-typo ; edit ; commit -am ; git push -u origin fix-typo', (sh) => { const o = sh.fs.lookup('/home/learner/origin.git'); const g = o && o.git; if (!g || !g.branches['fix-typo'] || !g.branches.main) return false; const f = g.commits[g.branches['fix-typo']].tree['README.md']; const m = g.commits[g.branches.main].tree['README.md']; return /Team website/.test(f) && /Team site/.test(m); }, TEAM_LAB.concat(TEAM_FIX), { lab: { setup: TEAM_LAB, en: 'a bare origin.git with one commit on main, created by a teammate.', hi: 'ek bare origin.git jisme teammate ne main par ek commit kiya.' }, testSolve: TEAM_LAB.concat(TEAM_FIX) }),
      M('git-m4', 'Undo a bad commit without rewriting history', 'Kharab commit ko history badle bina undo karo', 'In ~/shop the commit "oops: everything is free" set the price to 0, and a later commit (tax) already builds on it. Undo ONLY the bad commit with a new commit, so that price.txt is 100 again, tax.txt stays and no history is rewritten. (Use the lab button.)', '~/shop mein commit "oops: everything is free" ne price 0 kar di, aur baad ke commit (tax) ne uske upar kaam kiya. SIRF kharab commit ko naye commit se undo karo, taaki price.txt phir 100 ho, tax.txt rahe aur history na badle. (Lab button use karo.)', 'git log --oneline ; git revert --no-edit HEAD~1', 'git log --oneline ; git revert --no-edit HEAD~1', (sh) => { const g = gOf(sh, '/home/learner/shop'); return !!g && countOf(g) >= 4 && /price=100/.test(LX.cat(sh, '/home/learner/shop/price.txt')) && !!sh.fs.lookup('/home/learner/shop/tax.txt') && sh.log.some((r) => /git revert/.test(r.cmd)); }, REV_LAB.concat(REV_FIX), { lab: { setup: REV_LAB, en: 'a shop repo with a bad commit in the middle of the history.', hi: 'shop repo jiski history ke beech mein ek kharab commit hai.' }, testSolve: REV_LAB.concat(REV_FIX) }),
      M('git-m5', 'Recover commits after a hard reset', 'Hard reset ke baad commits wapas lao', 'In ~/lab somebody ran git reset --hard HEAD~2 and the commits "v2: big feature" and "v3: bugfix" disappeared from git log. Bring the repository back so that HEAD is the "v3: bugfix" commit and the file app contains v3. (Use the lab button.)', '~/lab mein kisi ne git reset --hard HEAD~2 chalaya aur commits "v2: big feature" aur "v3: bugfix" git log se gayab ho gaye. Repository ko wapas aise lao ki HEAD "v3: bugfix" commit ho aur file app mein v3 ho. (Lab button use karo.)', 'git reflog ; git reset --hard HEAD@{1}', 'git reflog ; git reset --hard HEAD@{1}', (sh) => { const g = gOf(sh, '/home/learner/lab'); return !!g && /v3: bugfix/.test(msgOf(g)) && LX.cat(sh, '/home/learner/lab/app').trim() === 'v3'; }, LOST_LAB.concat(LOST_FIX), { lab: { setup: LOST_LAB, en: 'a repo where two commits were wiped by a hard reset.', hi: 'repo jisme hard reset se do commits mit gaye.' }, testSolve: LOST_LAB.concat(LOST_FIX) }),
      M('git-m6', 'Keep secrets and junk out: .gitignore', 'Secrets aur kachra door rakho: .gitignore', 'The folder ~/app is a new repository with main.py, a .env file holding a password, a debug.log and a __pycache__ folder. Write a .gitignore so that Git ignores .env, *.log and __pycache__/, then commit so that ONLY main.py and .gitignore are tracked. (Use the lab button.)', '~/app naya repository hai jisme main.py, password wali .env file, debug.log aur __pycache__ folder hai. .gitignore likho taaki Git .env, *.log aur __pycache__/ ignore kare, phir aise commit karo ki SIRF main.py aur .gitignore tracked hon. (Lab button use karo.)', 'printf ".env\\n*.log\\n__pycache__/\\n" > .gitignore ; git add . ; git commit -m ...', 'printf ".env\\n*.log\\n__pycache__/\\n" > .gitignore ; git add . ; git commit -m ...', (sh) => { const g = gOf(sh, '/home/learner/app'); if (!g) return false; const h = headOf(g); return !!h && Object.keys(g.commits[h].tree).sort().join(',') === '.gitignore,main.py'; }, IGN_LAB.concat(IGN_FIX), { lab: { setup: IGN_LAB, en: 'a repo with a secret .env, a log and a cache folder lying around.', hi: 'repo jisme secret .env, log aur cache folder pade hain.' }, testSolve: IGN_LAB.concat(IGN_FIX) }),
      M('git-m7', 'A straight history with rebase', 'Rebase se seedhi history', 'In ~/rb the branch feature has one commit and main has moved on with another. Rebase feature onto main and fast-forward main, so that main contains both files (f and m), the history has NO merge commit and there are exactly 3 commits. (Use the lab button.)', '~/rb mein feature branch ka ek commit hai aur main ek aur commit se aage badh gayi. Feature ko main par rebase karo aur main ko fast-forward karo, taaki main mein dono files (f aur m) hon, history mein koi merge commit NA ho aur kul 3 commits hon. (Lab button use karo.)', 'git switch feature ; git rebase main ; git switch main ; git merge feature', 'git switch feature ; git rebase main ; git switch main ; git merge feature', (sh) => { const g = gOf(sh, '/home/learner/rb'); if (!g || !g.branches.main) return false; const h = g.branches.main; const t = g.commits[h].tree; const all = [...GI().ancestors(g, h)]; return 'f' in t && 'm' in t && all.length === 3 && all.every((x) => g.commits[x].parents.length < 2); }, REB_LAB.concat(REB_FIX), { lab: { setup: REB_LAB, en: 'a repo where feature and main have diverged.', hi: 'repo jisme feature aur main alag ho gayi hain.' }, testSolve: REB_LAB.concat(REB_FIX) }),
    ],
    quiz: [
      mcq(1, 'Which area holds the changes you have marked with git add but not yet committed?', 'git add se chune gaye par abhi commit na hue badlav kis jagah rehte hain?', ['The working tree', 'The staging area (index)', 'The remote', 'The reflog'], 1, 'Edit in the working tree, add to the staging area, commit into the repository.', 'Working tree mein edit, staging area mein add, repository mein commit.'),
      mcq(2, 'What does git pull do?', 'git pull kya karta hai?', ['It only uploads your commits', 'It deletes your local branch', 'It fetches the remote changes and merges them into your current branch', 'It creates a new repository'], 2, 'pull = fetch + merge (or fetch + rebase with --rebase).', 'pull = fetch + merge (ya --rebase ke saath fetch + rebase).'),
      cmd(3, 'Create a new Git repository in the existing folder ~/demo.', 'Maujooda folder ~/demo mein naya Git repository banao.', { setup: GIT0.concat(['mkdir ~/demo']), cwd: '~', verify: (sh) => !!gOf(sh, '/home/learner/demo'), sample: 'git init demo', alt: ['cd demo && git init', 'git init ~/demo', 'git -C demo init'], wrong: ['git init', 'git clone demo'], hintEn: 'git init, and tell it which folder.', hintHi: 'git init, aur folder batao.' }, 'git init creates the hidden .git folder where the history lives.', 'git init chhupa .git folder banata hai jahan history rehti hai.'),
      cmd(4, 'Stage a.txt and commit it with the message "add a" (one line is fine).', 'a.txt ko stage karo aur message "add a" ke saath commit karo (ek line chalegi).', { setup: GIT0.concat(['mkdir ~/p', 'cd ~/p', 'git init', 'echo hi > a.txt']), cwd: '~/p', verify: (sh) => { const g = gOf(sh, '/home/learner/p'); return !!g && msgOf(g) === 'add a' && 'a.txt' in g.commits[headOf(g)].tree; }, sample: 'git add a.txt && git commit -m "add a"', alt: ['git add . && git commit -m "add a"', 'git add -A && git commit -m "add a"', 'git add a.txt; git commit -m "add a"'], wrong: ['git commit -m "add a"', 'git add a.txt'], hintEn: 'add first, then commit -m.', hintHi: 'pehle add, phir commit -m.' }, 'A brand-new file must be staged with git add; commit -m alone has nothing to save.', 'Bilkul nayi file ko git add se stage karna padta hai; akela commit -m ke paas save karne ko kuch nahi.'),
      cmd(5, 'Show the history of the repository as one short line per commit.', 'Repository ki history har commit ke liye ek chhoti line mein dikhao.', { setup: Q_REPO, cwd: '~/p', verify: (sh, r) => LX.stripAnsi(r.out).split('\n').filter((l) => /^[0-9a-f]{7,40}\b/.test(l)).length === 3, sample: 'git log --oneline', alt: ['git --no-pager log --oneline', 'git log --pretty=oneline', 'git log --oneline -3'], wrong: ['git log', 'git status'], hintEn: 'git log with the compact option.', hintHi: 'git log compact option ke saath.' }, '--oneline prints the short hash and the subject, one commit per line.', '--oneline chhota hash aur subject chhapta hai, har commit ek line.'),
      cmd(6, 'Create a new branch called feature AND switch to it, in one command.', 'feature naam ki nayi branch banao AUR usme jao, ek hi command mein.', { setup: GIT0.concat(['mkdir ~/p', 'cd ~/p', 'git init', 'echo 1 > f', 'git add .', 'git commit -m one']), cwd: '~/p', verify: (sh) => { const g = gOf(sh, '/home/learner/p'); return !!g && GI().branchName(g) === 'feature'; }, sample: 'git switch -c feature', alt: ['git checkout -b feature', 'git switch --create feature'], wrong: ['git branch feature', 'git switch feature'], hintEn: 'switch with the create flag.', hintHi: 'switch create flag ke saath.' }, 'switch -c (or checkout -b) creates and enters the branch; git branch feature would only create it.', 'switch -c (ya checkout -b) branch banata aur usme jata hai; git branch feature sirf banata.'),
      cmd(7, 'Find out who last changed each line of f.txt.', 'Pata karo f.txt ki har line aakhri baar kisne badli.', { setup: Q_REPO, cwd: '~/p', verify: (sh, r) => LX.stripAnsi(r.out).split('\n').filter((l) => /\(Asha Rao\s+\d{4}-\d\d-\d\d/.test(l)).length === 3, sample: 'git blame f.txt', alt: ['git blame -- f.txt'], wrong: ['git log f.txt', 'git diff f.txt'], hintEn: 'The command named after assigning blame.', hintHi: 'Wo command jiska naam blame dene par hai.' }, 'git blame prints the commit, author and date next to every line.', 'git blame har line ke saath commit, author aur date chhapta hai.'),
      cmd(8, 'The last commit was a mistake that is already pushed. Undo it SAFELY by adding a new commit that reverses it (no editor).', 'Aakhri commit galti thi aur push ho chuka hai. Use SURAKSHIT tareeke se undo karo: use ulta karne wala naya commit jodo (editor nahi).', { setup: GIT0.concat(['mkdir ~/p', 'cd ~/p', 'git init', 'echo 1 > x', 'git add .', 'git commit -m one', 'echo 2 > x', 'git commit -am two']), cwd: '~/p', verify: (sh) => { const g = gOf(sh, '/home/learner/p'); return !!g && countOf(g) === 3 && LX.cat(sh, '/home/learner/p/x').trim() === '1'; }, sample: 'git revert --no-edit HEAD', alt: ['git revert HEAD --no-edit'], wrong: ['git reset --hard HEAD~1', 'git revert HEAD~5'], hintEn: 'revert, and skip the editor with --no-edit.', hintHi: 'revert, aur --no-edit se editor chhodo.' }, 'revert adds a new commit that cancels the old one, so shared history stays intact. reset would rewrite it.', 'revert purane ko cancel karne wala naya commit jodta hai, isliye shared history safe rehti hai. reset use badal deta.'),
      mcq(9, 'Which is the golden rule about rebase and other history rewriting?', 'Rebase aur history badalne wale commands ka sunehra niyam kaun sa hai?', ['Always rebase main before every push', 'Only rewrite commits that nobody else has pulled yet; use revert for shared ones', 'Rebase is always safer than merge', 'Use git push --force so that the server accepts it'], 1, 'Rewriting changes commit hashes; teammates who already have the old ones would be left with a diverged, confusing history.', 'Rewrite se commit hash badal jate hain; jin teammates ke paas purane hain unke paas bikhri, uljhi history reh jati.'),
      cmd(10, 'Boss level: you ran git reset --hard HEAD~1 and the commit "important" vanished. Bring it back in ONE command.', 'Boss level: tumne git reset --hard HEAD~1 chalaya aur commit "important" gayab ho gaya. Use EK command mein wapas lao.', { setup: GIT0.concat(['mkdir ~/p', 'cd ~/p', 'git init', 'echo 1 > x', 'git add .', 'git commit -m base', 'echo 2 > x', 'git commit -am important', 'git reset --hard HEAD~1']), cwd: '~/p', verify: (sh) => { const g = gOf(sh, '/home/learner/p'); return !!g && msgOf(g) === 'important' && LX.cat(sh, '/home/learner/p/x').trim() === '2'; }, sample: 'git reset --hard HEAD@{1}', alt: ['git reset --hard @{1}'], wrong: ['git reset --hard HEAD', 'git revert HEAD'], hintEn: 'The reflog remembers where HEAD was one move ago.', hintHi: 'Reflog yaad rakhta hai HEAD ek move pehle kahan tha.' }, 'HEAD@{1} is the position before the reset; resetting to it restores the commit and the file.', 'HEAD@{1} reset se pehle ki position hai; wahan reset karne se commit aur file wapas aa jati hain.'),
    ],
  });
})();
